<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
require_permission('maintenance.manage');
ensure_taxonomy_schema(); ensure_v8_schema(); ensure_v9_schema();
$pdo->exec("CREATE TABLE IF NOT EXISTS admin_activity (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, admin_id INT UNSIGNED NULL, admin_name VARCHAR(120) NOT NULL DEFAULT '', action VARCHAR(80) NOT NULL, entity_type VARCHAR(50) NOT NULL DEFAULT 'system', entity_id BIGINT NULL, summary VARCHAR(240) NOT NULL DEFAULT '', ip_hash CHAR(64) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_activity_created(created_at), INDEX idx_activity_entity(entity_type,entity_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$error=''; $notice='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf();
 if (($_POST['action']??'')==='save_cache_settings') {
  $ranges=['cache_ttl_posts'=>[15,300],'cache_ttl_article'=>[15,600],'cache_ttl_categories'=>[15,600],'cache_ttl_feeds'=>[30,1800]];
  $stmt=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');
  foreach($ranges as $key=>$range){$value=max($range[0],min($range[1],(int)($_POST[$key]??0)));$stmt->execute([$key,(string)$value]);}
  cache_clear(); nowrd_audit('cache.settings_updated','system',null,'Cache TTL settings updated'); $notice='Pengaturan cache berhasil disimpan.';
 }
 if (($_POST['action']??'')==='clear_cache') { cache_clear(); nowrd_audit('cache.cleared','system',null,'Public cache version rotated'); $notice='Cache dibersihkan. File lama akan kedaluwarsa dan tidak lagi digunakan.'; }
 if (($_POST['action']??'')==='export_sql_backup') {
  if (($_POST['confirm_backup'] ?? '') !== 'yes') {
   $error='Centang konfirmasi sebelum membuat backup SQL.';
  } else try {
   $tableRows=$pdo->query("SHOW FULL TABLES WHERE Table_type = 'BASE TABLE'")->fetchAll(PDO::FETCH_NUM);
   $tableNames=[];
   foreach($tableRows as $tableRow){$name=(string)$tableRow[0];if(preg_match('/^[A-Za-z0-9_]+$/',$name))$tableNames[]=$name;}
   // Create referenced tables before dependent tables; drop in reverse order.
   $priority=['users','settings','posts','categories','tags','media','post_categories','post_tags','post_revisions','admin_activity','login_attempts'];
   usort($tableNames,static function($a,$b)use($priority){$ia=array_search($a,$priority,true);$ib=array_search($b,$priority,true);$ia=$ia===false?1000:$ia;$ib=$ib===false?1000:$ib;return $ia<=>$ib?:strcmp($a,$b);});
   $sql="-- NOWRD CMS database backup\n-- Generated: ".gmdate('c')."\n-- Contains database rows, including password hashes and audit records. Protect this file.\n-- Restore only into a separate/empty database after reviewing the contents.\n\nSET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n\n";
   foreach(array_reverse($tableNames) as $table){$quoted='`'.str_replace('`','``',$table).'`';$sql.='DROP TABLE IF EXISTS '.$quoted.";\n";}
   $sql.="\n";
   foreach($tableNames as $table) {
    $quoted='`'.str_replace('`','``',$table).'`';
    $create=$pdo->query('SHOW CREATE TABLE '.$quoted)->fetch(PDO::FETCH_NUM);
    if (!$create || empty($create[1])) continue;
    $sql.=$create[1].";\n\n";
    $rows=$pdo->query('SELECT * FROM '.$quoted);
    while($row=$rows->fetch(PDO::FETCH_ASSOC)) {
     $columns=array_keys($row);
     $quotedColumns=array_map(static fn($column)=>'`'.str_replace('`','``',(string)$column).'`',$columns);
     $values=[];
     foreach($row as $value) $values[]=$value===null?'NULL':$pdo->quote((string)$value);
     $sql.='INSERT INTO '.$quoted.' ('.implode(',',$quotedColumns).') VALUES ('.implode(',',$values).");\n";
    }
    $sql.="\n";
   }
   $sql.="SET FOREIGN_KEY_CHECKS=1;\n";
   nowrd_audit('backup.sql_exported','backup',null,'Full SQL database backup generated');
   header('Content-Type: application/sql; charset=utf-8');
   header('Content-Disposition: attachment; filename="nowrd-database-backup-'.gmdate('Y-m-d').'.sql"');
   header('Cache-Control: no-store, private');
   echo $sql; exit;
  } catch(Throwable $e){ error_log('NOWRD SQL backup failed: '.$e->getMessage()); $error='Backup SQL tidak berhasil. Periksa log server dan izin database.'; }
 }
 if (($_POST['action']??'')==='export_content') {
  try {
   $tables=['posts','categories','tags','post_categories','post_tags','settings','media','post_revisions']; $data=[];
   foreach($tables as $table){
    $exists=$pdo->prepare('SHOW TABLES LIKE ?'); $exists->execute([$table]);
    if($exists->fetchColumn()) $data[$table]=$pdo->query('SELECT * FROM `'.$table.'`')->fetchAll(PDO::FETCH_ASSOC);
   }
   nowrd_audit('backup.content_exported','backup',null,'Content JSON export generated');
   $payload=['product'=>'NOWRD CMS','type'=>'content-backup-json','schema_version'=>15,'exported_at'=>gmdate('c'),'notice'=>'JSON data export only. Uploaded media binaries, users/password hashes, config.php, and database credentials are not included. Keep a separate database + uploads backup.','tables'=>$data];
   header('Content-Type: application/json; charset=utf-8'); header('Content-Disposition: attachment; filename="nowrd-content-backup-'.gmdate('Y-m-d').'.json"');
   echo json_encode($payload,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); exit;
  } catch(Throwable $e){ error_log('NOWRD content export failed: '.$e->getMessage()); $error='Ekspor tidak berhasil. Periksa log server dan izin database.'; }
 }
}
$checks=[];
$checks[]=['Database connection','Connected','ok'];
$checks[]=['Admin idle timeout','30 minutes','ok'];
$checks[]=['Login rate limiter','Enabled','ok'];
$checks[]=['PHP version',PHP_VERSION,version_compare(PHP_VERSION,'8.1.0','>=')?'ok':'warn'];
$checks[]=['PDO MySQL driver',extension_loaded('pdo_mysql')?'Available':'Missing',extension_loaded('pdo_mysql')?'ok':'warn'];
$checks[]=['JSON extension',extension_loaded('json')?'Available':'Missing',extension_loaded('json')?'ok':'warn'];
$checks[]=['Fileinfo extension',extension_loaded('fileinfo')?'Available':'Missing',extension_loaded('fileinfo')?'ok':'warn'];
$checks[]=['mbstring extension',extension_loaded('mbstring')?'Available (recommended)':'Missing (optional)',extension_loaded('mbstring')?'ok':'warn'];
$cacheDiagnostics=nowrd_cache_stats();
$checks[]=['Public query cache',$cacheDiagnostics['enabled']?'Enabled':'Unavailable — direct queries', $cacheDiagnostics['enabled']?'ok':'warn'];
$checks[]=['Cache directory writable',$cacheDiagnostics['enabled']?'Writable':'Not writable', $cacheDiagnostics['enabled']?'ok':'warn'];
$checks[]=['PHP upload limit',ini_get('upload_max_filesize').' / post '.ini_get('post_max_size'),'ok'];
$checks[]=['Memory limit',ini_get('memory_limit') ?: 'Host default','ok'];
$cacheTtls=['cache_ttl_posts'=>nowrd_cache_ttl('cache_ttl_posts',45,15,300),'cache_ttl_article'=>nowrd_cache_ttl('cache_ttl_article',60,15,600),'cache_ttl_categories'=>nowrd_cache_ttl('cache_ttl_categories',60,15,600),'cache_ttl_feeds'=>nowrd_cache_ttl('cache_ttl_feeds',120,30,1800)];
$checks[]=['Uploads directory',is_dir(dirname(__DIR__).'/uploads/media')?'Available':'Missing',is_dir(dirname(__DIR__).'/uploads/media')&&is_writable(dirname(__DIR__).'/uploads/media')?'ok':'warn'];
$checks[]=['Configuration file',is_file(dirname(__DIR__).'/config.php')?'Present':'Missing',is_file(dirname(__DIR__).'/config.php')?'ok':'warn'];
$checks[]=['HTTPS',((!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||($_SERVER['HTTP_X_FORWARDED_PROTO']??'')==='https')?'Detected':'Not detected',((!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||($_SERVER['HTTP_X_FORWARDED_PROTO']??'')==='https')?'ok':'warn'];
$counts=[]; foreach(['posts','users','media','categories','tags','post_revisions'] as $t){try{$counts[$t]=(int)$pdo->query('SELECT COUNT(*) FROM `'.$t.'`')->fetchColumn();}catch(Throwable $e){$counts[$t]=null;}}
$activities=$pdo->query('SELECT admin_name,action,entity_type,entity_id,summary,created_at FROM admin_activity ORDER BY id DESC LIMIT 50')->fetchAll();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Maintenance — NOWRD</title><link rel="stylesheet" href="<?=e(base_url('public/assets/style.css'))?>"><style>
.maint{max-width:1160px;padding:clamp(22px,4vw,48px);margin:auto}.maint-head{display:flex;justify-content:space-between;align-items:end;gap:18px;flex-wrap:wrap;margin-bottom:28px}.maint-head h1{font-size:clamp(32px,5vw,48px);letter-spacing:-1.8px;margin:8px 0}.maint-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.maint-card{background:var(--card,#fff);border:1px solid var(--line);border-radius:18px;padding:22px;min-width:0}.maint-card h2{margin:6px 0 8px}.maint-muted{color:var(--muted);font-size:13px;line-height:1.65}.health-list{display:grid;gap:0;margin-top:16px}.health-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-top:1px solid var(--line);font-size:13px}.status{font-size:11px;border:1px solid var(--line);border-radius:99px;padding:5px 9px;white-space:nowrap}.status.ok{background:#edf7e8;color:#305c1c}.status.warn{background:#fff5df;color:#805400}.count-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:16px}.count-box{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:14px}.count-box strong{display:block;font-size:24px;letter-spacing:-1px}.count-box span{font-size:11px;color:var(--muted)}.maint-table{width:100%;border-collapse:collapse;margin-top:16px;font-size:12px}.maint-table th,.maint-table td{text-align:left;vertical-align:top;padding:11px 8px;border-top:1px solid var(--line);overflow-wrap:anywhere}.maint-table th{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.06em}.maint-table td small{display:block;color:var(--muted);margin-top:4px}.maint-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.maint-actions .button{margin:0}.maint-wide{grid-column:1/-1;overflow:hidden}.maint-wide .table-wrap{overflow:auto}.maint-note{font-size:12px;line-height:1.65;color:var(--muted);background:var(--paper);padding:12px;border-radius:10px;margin-top:14px}@media(max-width:780px){.maint-grid{grid-template-columns:1fr}.maint-wide{grid-column:auto}}@media(max-width:450px){.count-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.maint-card{padding:17px}}
</style></head><body class="dashboard"><aside class="sidebar"><a class="brand" href="<?=e(base_url('admin/index.php'))?>"><span class="brand-mark"><?=e(setting('brand_mark','n.'))?></span> <?=e(setting('brand_name','NOWRD'))?></a><div class="side-label">WORKSPACE</div><a class="side-link" href="<?=e(base_url('admin/index.php'))?>">▦ &nbsp; Overview</a><a class="side-link" href="<?=e(base_url('admin/post.php'))?>">✎ &nbsp; New story</a><a class="side-link" href="<?=e(base_url('admin/media.php'))?>">▧ &nbsp; Media Library</a><a class="side-link" href="<?=e(base_url('admin/taxonomies.php'))?>">◇ &nbsp; Categories & Tags</a><a class="side-link" href="<?=e(base_url('admin/settings.php'))?>">⚙ &nbsp; Settings</a><a class="side-link" href="<?=e(base_url('admin/users.php'))?>">♙ &nbsp; Admin accounts</a><a class="side-link active" href="<?=e(base_url('admin/maintenance.php'))?>">⌁ &nbsp; Maintenance</a><a class="side-link" href="<?=e(base_url('index.php'))?>">↗ &nbsp; View website</a></aside><main class="admin-main"><div class="maint"><header class="maint-head"><div><div class="eyebrow">WORKSPACE / OPERATIONS</div><h1>Maintenance<span class="lime">.</span></h1><p class="maint-muted">A quiet place to check the installation, keep a record of important changes, and export content data.</p></div><a class="button" href="<?=e(base_url('admin/settings.php'))?>">Settings ↗</a></header><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="alert"><?=e($notice)?></div><?php endif;?><div class="maint-grid"><section class="maint-card"><div class="eyebrow">01 / HEALTH CHECK</div><h2>Installation status</h2><p class="maint-muted">A lightweight diagnostic based on the current request. It does not modify your installation.</p><div class="health-list"><?php foreach($checks as $c):?><div class="health-row"><span><?=e($c[0])?></span><span class="status <?=e($c[2])?>"><?=e($c[1])?></span></div><?php endforeach;?></div><div class="maint-note">A warning is not always a failure. HTTPS detection may depend on your hosting proxy configuration. Confirm security settings with your hosting provider.</div></section><section class="maint-card"><div class="eyebrow">02 / CACHE & PERFORMANCE</div><h2>Public query cache</h2><p class="maint-muted">Cache hit/miss totals are recorded locally on this server. Counts are cumulative until the stats file is reset by hosting maintenance; clearing cache rotates the active version.</p><div class="count-grid"><div class="count-box"><strong><?=number_format($cacheDiagnostics['hits'])?></strong><span>Cache hits</span></div><div class="count-box"><strong><?=number_format($cacheDiagnostics['misses'])?></strong><span>Cache misses</span></div><div class="count-box"><strong><?=number_format($cacheDiagnostics['writes'])?></strong><span>Cache writes</span></div></div><p class="maint-muted">Hit ratio: <?=($cacheDiagnostics['hits']+$cacheDiagnostics['misses'])>0?number_format(100*$cacheDiagnostics['hits']/($cacheDiagnostics['hits']+$cacheDiagnostics['misses']),1).'%':'Not enough data'?> · <?=e($cacheDiagnostics['updated_at'] ?: 'No cache events yet')?></p><form method="post" class="maint-actions"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><button class="button secondary" name="action" value="clear_cache" type="submit">Clear active cache</button></form><form method="post" style="margin-top:18px"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_cache_settings"><div class="health-list"><?php foreach([['cache_ttl_posts','Article listing TTL (seconds)',15,300],['cache_ttl_article','Article page TTL (seconds)',15,600],['cache_ttl_categories','Category list TTL (seconds)',15,600],['cache_ttl_feeds','RSS / sitemap TTL (seconds)',30,1800]] as $settingRow):?><label class="health-row"><span><?=e($settingRow[1])?></span><input type="number" name="<?=e($settingRow[0])?>" min="<?=$settingRow[2]?>" max="<?=$settingRow[3]?>" value="<?=$cacheTtls[$settingRow[0]]?>" style="width:110px"></label><?php endforeach;?></div><div class="maint-actions"><button class="button" type="submit">Save cache settings</button></div></form><div class="maint-note">Cache TTL is clamped server-side. This is not a full page cache and does not include admin pages. If the cache is unavailable, NOWRD falls back to database queries.</div></section><section class="maint-card"><div class="eyebrow">03 / CONTENT INVENTORY</div><h2>What lives here</h2><p class="maint-muted">Counts help you understand the scale of the publication before maintenance or migration.</p><div class="count-grid"><?php foreach(['posts'=>'Stories','users'=>'Admin accounts','media'=>'Media records','categories'=>'Categories','tags'=>'Tags','post_revisions'=>'Revisions'] as $k=>$label):?><div class="count-box"><strong><?= $counts[$k]===null?'—':number_format($counts[$k])?></strong><span><?=e($label)?></span></div><?php endforeach;?></div><div class="maint-actions"><a class="button secondary" href="<?=e(base_url('admin/index.php'))?>">Review stories</a><a class="button secondary" href="<?=e(base_url('admin/media.php'))?>">Review media</a></div></section><section class="maint-card"><div class="eyebrow">04 / PORTABLE DATA</div><h2>Export content JSON</h2><p class="maint-muted">Download structured content records for documentation, migration planning, or offline inspection.</p><form method="post" class="maint-actions"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><button class="button" type="submit" name="action" value="export_content">Export content data ↓</button></form><div class="maint-note"><b>Important:</b> this export contains article and related database records, but excludes user accounts/password hashes, database credentials, and actual media files. Keep separate database and <code>uploads/</code> backups. This JSON export is not a one-click restore package.</div></section><section class="maint-card"><div class="eyebrow">05 / DATABASE BACKUP</div><h2>Download SQL backup</h2><p class="maint-muted">Create a SQL dump of database tables and records, including admin password hashes. No database credentials or uploaded file binaries are included.</p><form method="post" class="maint-actions" onsubmit="return confirm('Buat file backup SQL? Simpan file ini di lokasi privat.');"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label style="display:flex;align-items:flex-start;gap:8px;max-width:100%;font-size:12px;line-height:1.5"><input type="checkbox" name="confirm_backup" value="yes" required style="margin-top:3px"> Saya memahami file berisi data database sensitif dan akan menyimpannya secara aman.</label><button class="button" type="submit" name="action" value="export_sql_backup">Download SQL backup ↓</button></form><div class="maint-note"><b>Perhatian:</b> file SQL berisi perintah DROP TABLE sebelum membuat ulang tabel. Jangan impor ke database produksi aktif. Pulihkan hanya ke database kosong/terpisah setelah memeriksa file. File media perlu dicadangkan terpisah dari folder <code>uploads/</code>.</div></section><section class="maint-card"><div class="eyebrow">06 / MAINTENANCE ROUTINE</div><h2>Before changing versions</h2><ul class="maint-muted"><li>Back up the database using your hosting panel or database tool.</li><li>Download the full <code>uploads/</code> directory.</li><li>Keep <code>config.php</code> private and out of public repositories.</li><li>Test updates on a staging copy before replacing production files.</li><li>Verify login, article editing, publishing, and media after deployment.</li></ul><div class="maint-note">NOWRD does not run automated background jobs from this page. Health status reflects the current web request only.</div></section><section class="maint-card maint-wide"><div class="eyebrow">07 / AUDIT TRAIL</div><h2>Recent admin activity</h2><p class="maint-muted">Records important actions without saving article bodies, passwords, or raw IP addresses. The IP value, when available, is stored only as a one-way hash.</p><div class="table-wrap"><table class="maint-table"><thead><tr><th>When</th><th>Who</th><th>Action</th><th>Item</th></tr></thead><tbody><?php if(!$activities):?><tr><td colspan="4" class="maint-muted">No activity has been recorded yet. New article saves and settings changes will appear here.</td></tr><?php else:foreach($activities as $a):?><tr><td><?=e($a['created_at'])?></td><td><?=e($a['admin_name'])?></td><td><?=e($a['action'])?></td><td><?=e($a['entity_type'])?><?= $a['entity_id']?' #'.(int)$a['entity_id']:''?><small><?=e($a['summary'])?></small></td></tr><?php endforeach;endif;?></tbody></table></div></section></div></div></main><script>window.NOWRD_VISUAL = <?=json_encode(nowrd_visual_preferences(), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>; window.NOWRD_VISUAL_ADMIN = true; window.NOWRD_CSRF = <?=json_encode(csrf_token())?>; window.NOWRD_VISUAL_SAVE_URL = <?=json_encode(base_url('admin/visual-settings.php'))?>;</script><script src="<?=e(base_url('public/assets/ui-v10.js'))?>" defer></script></body></html>
